/**
 * @file ScreenLayoutComposer.tsx
 * @description WYSIWYG canvas editor for Ren'Py `screen` layouts.
 * Drag widgets from the palette onto the dark game canvas, drag to reposition,
 * drag corner handles to resize, double-click text to edit inline.
 * Hierarchy managed via the Layers panel. Code generated by `lib/screenCodeGenerator`.
 */
import React, { useState, useCallback, useRef, useEffect } from 'react';
import type { ScreenLayoutComposition, ScreenWidget, ScreenWidgetType } from '@/types';
import { generateScreenCode } from '@/lib/screenCodeGenerator';
import { createId } from '@/lib/createId';
import CodeActionButtons from './CodeActionButtons';
import type * as monaco from 'monaco-editor/esm/vs/editor/editor.api';

interface ScreenLayoutComposerProps {
    composition: ScreenLayoutComposition;
    onCompositionChange: (value: React.SetStateAction<ScreenLayoutComposition>) => void;
    screenName: string;
    onRenameScreen: (newName: string) => void;
    labels: string[];
    isLocked?: boolean;
    isActive?: boolean;
    onDuplicate?: () => void;
    onGoToCode?: () => void;
    activeEditor?: monaco.editor.IStandaloneCodeEditor | null;
}

